function longestFreshStretch(playlist) {
  const last = new Map()
  let left = 0
  let best = 0
  for (let r = 0; r < playlist.length; r++) {
    const c = playlist[r]
    if (last.has(c)) left = Math.max(left, last.get(c) + 1)
    last.set(c, r)
    best = Math.max(best, r - left + 1)
  }
  return best
}

