def longest_fresh_stretch(playlist):
    last = {}
    left = 0
    best = 0
    for r, c in enumerate(playlist):
        if c in last:
            left = max(left, last[c] + 1)
        last[c] = r
        best = max(best, r - left + 1)
    return best
